export const POLL_MS = 2000;

export async function watchJob(api, id, wait) {
  let job = await api.getJob(id);
  while (job.status !== "complete" && job.status !== "failed") {
    await wait(POLL_MS);
    job = await api.getJob(id);
  }
  return job;
}

